input.command:
mkdir -p src/inngest src/app/api/inngest
cat > src/inngest/client.ts <<'EOF'
import { Inngest } from "inngest";

// Locally (INNGEST_DEV=1) no keys are needed; in production the SDK reads
// INNGEST_EVENT_KEY and INNGEST_SIGNING_KEY from the environment.
export const inngest = new Inngest({ id: "notely" });
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

export const REMINDER_DELAY = "10m";

export const userReminder = inngest.createFunction(
  {
    id: "user-reminder",
    retries: 4, // up to 5 attempts total, with Inngest's exponential backoff
    triggers: [{ event: "notely/user.created" }],
  },
  async ({ event, step }) => {
    await step.sleep("wait-before-reminder", REMINDER_DELAY);
    await step.run("log-reminder", async () => {
      const { userId, email, name } = event.data;
      console.log(`[reminder] Hi ${name} (${email}), user ${userId} was created ${REMINDER_DELAY} ago.`);
    });
  },
);

export const functions = [userReminder];
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { functions } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions });
EOF
cat > .env.example <<'EOF'
# Inngest (background jobs). Get real values from https://app.inngest.com
INNGEST_EVENT_KEY=your-event-key-placeholder
INNGEST_SIGNING_KEY=signkey-prod-placeholder

# Local development: set to 1 and run `npx inngest-cli@latest dev` (no keys needed)
# INNGEST_DEV=1
EOF
printf '!.env.example\n' >> .gitignore
python3 - <<'EOF'
p="src/lib/users.ts"
s=open(p).read()
s='import { inngest } from "@/inngest/client";\n\n'+s
s=s.replace('''export async function listUsers''','''export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString(),
  };
  users.push(user);

  // The reminder job runs 10 minutes later (see src/inngest/functions.ts).
  // Don't fail user creation if the queue is unreachable.
  try {
    await inngest.send({
      name: "notely/user.created",
      data: { userId: user.id, email: user.email, name: user.name },
    });
  } catch (err) {
    console.error("Failed to schedule reminder job", err);
  }
  return user;
}

export async function listUsers''',1)
open(p,"w").write(s)
EOF
